# Generated by secure-by-design v0.1.0 for DPDP §9 (Children's data).
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/children_gate.md
#
# Gates any code path that processes data of a data principal under 18.
# DPDP §9 requires VERIFIABLE parental consent; this scaffold provides the
# API shape but the actual verification provider is YOUR choice (e.g.
# DigiLocker, government-eID OTP, in-person, video KYC).
#
# THIS IS A SCAFFOLD. Do NOT ship to production without implementing a real
# parent-consent verification flow and having it reviewed by counsel.

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Literal, NoReturn, Protocol

from fastapi import HTTPException

from ..security.audit_log import audit_log
from .consent import ConsentRecord, record_consent

ParentRelation = Literal['mother', 'father', 'legal-guardian']


@dataclass(frozen=True)
class ParentalConsentRequest:
    child_data_principal_id: str
    parent_claimed_relation: ParentRelation
    parent_contact: str          # PII — handle with care
    consent_text_hash: str
    notice_version: str


@dataclass(frozen=True)
class ParentalConsentResult:
    verified: bool
    method: str                  # e.g. 'digilocker', 'otp-aadhaar-linked', 'video-kyc'
    verified_at: datetime
    parent_identifier: str | None = None  # pseudonymous (hash of govt-ID, not raw)


class ParentalConsentVerifier(Protocol):
    async def verify(self, request: ParentalConsentRequest) -> ParentalConsentResult:
        """
        Verify that the named parent/guardian has given consent for the specified child.
        Implementation choices: DigiLocker / OTP-against-parent-Aadhaar-linked-mobile /
        video-KYC by a registered practitioner / in-person at clinic.
        Returns a verification token + the verified parent's identifier.
        """
        ...


_verifier: ParentalConsentVerifier | None = None


def set_parental_consent_verifier(verifier: ParentalConsentVerifier) -> None:
    global _verifier
    _verifier = verifier


@dataclass(frozen=True)
class ChildContext:
    child_data_principal_id: str
    age_years: int               # computed from DOB by your auth layer
    purpose: str                 # specific purpose, e.g. 'patient.consultation.book'
    category: str                # dataCategory name from manifest
    notice_version: str
    consent_text_hash: str
    parent_claimed_relation: ParentRelation
    parent_contact: str


class ParentalConsentRequiredError(HTTPException):
    code = 'PARENTAL_CONSENT_REQUIRED'

    def __init__(self) -> None:
        super().__init__(status_code=451, detail='DPDP §9: verifiable parental consent could not be established.')


async def verify_parental_consent(ctx: ChildContext) -> None:
    """
    Gate function — call BEFORE any storage / AI processing of children's data.
    Raises if verifiable parental consent is not on file.

    DPDP §9(1) requires verifiable parental / lawful-guardian consent for
    processing children's data. §9(2) prohibits tracking, behavioural monitoring,
    and targeted advertising directed at children — those are out of scope here
    and must be designed out of your product.
    """
    if ctx.age_years >= 18:
        # Adult — gate not applicable. The caller should have routed to standard consent.
        return

    if _verifier is None:
        raise RuntimeError(
            'secure-by-design: ParentalConsentVerifier not configured. '
            'A children-data path requires DPDP §9 verifiable parental consent — wire up a verifier at boot.'
        )

    result = await _verifier.verify(ParentalConsentRequest(
        child_data_principal_id=ctx.child_data_principal_id,
        parent_claimed_relation=ctx.parent_claimed_relation,
        parent_contact=ctx.parent_contact,
        consent_text_hash=ctx.consent_text_hash,
        notice_version=ctx.notice_version,
    ))

    if not result.verified:
        await audit_log.security(
            'children.consent.denied',
            target=ctx.child_data_principal_id,
            severity='WARN',
            outcome='denied',
            attrs={'purpose': ctx.purpose, 'method': result.method},
        )
        raise ParentalConsentRequiredError()

    # Record alongside the standard consent chain so /dsr/access surfaces it.
    await record_consent(ConsentRecord(
        data_principal_id=ctx.child_data_principal_id,
        purpose=ctx.purpose,
        category=ctx.category,
        basis='explicit',
        notice_version=ctx.notice_version,
        consent_text_hash=ctx.consent_text_hash,
        language='en',
        given_by_actor='parent-guardian',
        channel='web',
    ))

    await audit_log.security(
        'children.consent.recorded',
        target=ctx.child_data_principal_id,
        actor=result.parent_identifier or 'parent:unknown',
        severity='NOTICE',
        outcome='success',
        attrs={'purpose': ctx.purpose, 'method': result.method, 'verified_at': result.verified_at.isoformat()},
    )


def refuse_children_profiling(reason: str) -> NoReturn:
    """
    Sentinel guard to use anywhere children's data MAY be processed.
    Behavioural tracking, profiling, and targeted ads to children are prohibited
    by §9(2) — this helper raises unconditionally if invoked on such a code path.
    """
    raise RuntimeError(f'DPDP §9(2) prohibits this for children: {reason}')
